Global Load Balancer with Cloud Armor.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(Global_Load_Balancer_with_Cloud_Armor, "Global Load Balancer with Cloud Armor") {
    Component(Anycast_IP_Termination, "Anycast IP Termination", "Google Cloud Global Load Balancer", "Terminates incoming HTTPS and WebSocket traffic globally and routes to the nearest region.")
    Component(Web_Application_Firewall_WAF_Rate_Limiting, "Web Application Firewall (WAF) & Rate Limiting", "Cloud Armor", "Provides geo-based rate-limiting, DDoS protection, and security filtering for incoming traffic.")
}

Rel(Anycast_IP_Termination, Web_Application_Firewall_WAF_Rate_Limiting, "Inspects and filters incoming traffic", "")
@enduml

API Gateway / BFF.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(api_gateway_bff, "API Gateway / BFF") {
    Component(region_router, "Region Router & Enforcement Filter", "Go (Golang)", "Routes geo-targeted traffic and enforces data residency and regulatory compliance constraints.")
    Component(auth_interceptor, "Authentication & Consent Interceptor", "Go (Golang)", "Validates requests and manages authentication and consent.")
    Component(regional_service_router, "Regional Service Router", "Go (Golang)", "Forwards validated requests to downstream regional services.")
}

Rel(auth_interceptor, regional_service_router, "Forwards validated requests", "In-process function call")

@enduml

AI Orchestrator.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(ai_orchestrator, "AI Orchestrator") {
    Component(Prompt_Router, "Prompt Router", "Python, FastAPI", "Passes sanitized, region-validated payloads to the Model Gateway.")
    Component(Model_Gateway, "Model Gateway", "Python, FastAPI", "Executes external inference requests and emits immutable audit events.")
    Component(Traceability_Logger, "Traceability Logger", "Python, FastAPI", "Emits and persists immutable audit events to region-locked storage.")
}

Rel(Prompt_Router, Model_Gateway, "Passes sanitized, region-validated payloads", "In-process async function calls")
Rel(Model_Gateway, Traceability_Logger, "Emits immutable audit events", "In-process Python Queue")

@enduml
